{
  "status": "updated",
  "chapter_updates": [
    {
      "chapter_id": "CH1",
      "updated_plan": {
        "thesis": "可见光消色差超构透镜的带宽与视场性能受限于两个独立的物理边界：一是基于局部相位调控的色散工程所面临的延迟 - 带宽积极限，其表现为随数值孔径（NA）增加而减小的带宽上限，以及因有限孔径群延迟需求非单调性导致的“带宽饱和”现象；二是单界面几何结构固有的高阶像差限制，导致高 NA 下有效成像视场极小（如 NA=0.5 时<5 µm）。这两重约束共同确立了单层超构透镜在宽视场宽带应用中的理论天花板。",
        "reader_objective": "读者将理解为何大视场并不必然导致带宽线性崩溃，而是存在一个由系统几何决定的饱和阈值；同时认识到即使色散被完美校正，单界面设计仍无法克服几何像差对视场的硬性截断，从而为后续章节探讨微观设计机制和实证评估提供明确的物理基准。",
        "units": [
          {
            "unit_id": "U1",
            "theme": "延迟 - 带宽积作为局部超表面的基本物理约束",
            "substantive_point": "确立局部超表面中最大群延迟范围决定可用带宽上限的基本不等式，并解释高 NA 器件带宽受限的首要原因。",
            "development": "首先引入 P0002 的核心推导，将每个超构原子建模为一维延迟线，建立局部相互作用下的基本不等式 ΔT · Δω ≤ κ。论证在消色差设计中，为了补偿不同波长下的相位差，所需的群延迟跨度随 NA 增加而急剧扩大，这是高 NA 器件带宽受限的根本原因。",
            "paragraph_briefs": [
              {
                "point": "建立局部超表面的延迟 - 带宽积极限模型",
                "development": "阐述 P0002 如何将超构原子简化为一维延迟线，并引用 Miller 的一般性界限，确立群延迟范围ΔT 与带宽Δω的反比关系。指出该模型是后续分析的理论基石。",
                "source_handles": [
                  "P0002"
                ]
              },
              {
                "point": "解释高 NA 对带宽的压缩效应",
                "development": "说明在消色差设计中，为了覆盖宽波段，透镜各位置需提供不同的群延迟以校正色差。随着 NA 增加，透镜边缘与中心的光程差增大，导致所需的最大群延迟跨度ΔT_max 显著增加，从而根据不等式限制了最大可用带宽。",
                "source_handles": [
                  "P0002"
                ]
              }
            ],
            "evidence_and_conditions": [
              {
                "source_handle": "P0002",
                "finding": "对于具有较大数值孔径（NA）的金属透镜，可实现的最大光谱带宽随 NA 的增加而减小。",
                "conditions": "研究对象为基于局部相互作用的平面金属透镜，假设标量近似和局部相位调控。"
              }
            ],
            "transition": "明确了 NA 对带宽的负面影响后，需要进一步分析视场角（FOV）如何影响这一界限，特别是澄清关于视场扩展导致带宽无限下降的直觉误区。"
          },
          {
            "unit_id": "U2",
            "theme": "群延迟需求的非单调性与带宽饱和机制",
            "substantive_point": "揭示有限孔径金属透镜上群延迟分布的非单调特性，论证“带宽饱和”现象的物理根源，修正简单的线性衰退预期。",
            "development": "深入分析 P0002 中群延迟 tg(r, α) 随角度变化的空间特性。反驳“入射角越大，所需补偿越大”的直觉，指出由于有限孔径效应，掠射角下所需相位范围反而最小。最大群延迟差值出现在特定临界角α*，当 FOV 超过该角度后，带宽界限趋于稳定。",
            "paragraph_briefs": [
              {
                "point": "群延迟分布的非单调性特征",
                "development": "基于 P0002 的数学推导，展示对于有限半径 R 的透镜，所需总相位范围（即群延迟范围）并不随入射角单调增加。在掠射角附近，由于有效孔径截断和光程差变化率降低，所需相位范围反而减小。",
                "source_handles": [
                  "P0002"
                ]
              },
              {
                "point": "带宽饱和现象的物理机制",
                "development": "解释决定带宽上限的是整个工作 FOV 内最宽的群延迟范围ΔT_max。当 FOV 扩大到包含产生最大群延迟差的临界角α*后，再增加 FOV（允许更大入射角）并不会产生更宽的群延迟范围，因为更大角度对应的群延迟范围更小。因此，带宽下限不再随 FOV 增加而显著下降，出现饱和。",
                "source_handles": [
                  "P0002"
                ]
              }
            ],
            "evidence_and_conditions": [
              {
                "source_handle": "P0002",
                "finding": "带宽限制的减小趋势在达到某个特定的 FOV 后会饱和。例如，对于固定 NA=0.7nb，FOV 为 180 度的金属透镜理论上可能具有与 FOV 为 60 度相同的带宽。",
                "conditions": "研究对象为平面金属透镜和平面焦面系统，基于局部相互作用假设。"
              }
            ],
            "transition": "饱和现象是有限孔径系统的内禀属性，接下来需确认这一结论在不同焦点映射几何下的稳健性。"
          },
          {
            "unit_id": "U3",
            "theme": "焦点几何映射对带宽界限的影响",
            "substantive_point": "对比无畸变（r0 = F tan(α)）与有畸变（r0 = F α）两种焦点定位策略，确认饱和现象的普遍性。",
            "development": "分析 P0002 中两种常见焦点定位策略的计算结果。虽然无畸变要求通常更严苛，绝对带宽数值存在差异，但‘随 FOV 增加而饱和’的核心物理趋势在两种情况下均稳健存在。这表明饱和是有限孔径系统的内禀属性，而非特定成像标准的产物。",
            "paragraph_briefs": [
              {
                "point": "两种焦点映射模型的带宽界限对比",
                "development": "对比 r0 = F tan(α)（无畸变）和 r0 = F α（线性映射，存在畸变）下的带宽计算结果。指出尽管无畸变模型对带宽的要求更严格，但两者均表现出随 FOV 增加带宽先减小后饱和的趋势。",
                "source_handles": [
                  "P0002"
                ]
              },
              {
                "point": "饱和现象的普适性确认",
                "development": "论证饱和现象不依赖于特定的焦点定义方式，而是源于有限孔径几何结构带来的群延迟需求非单调性。这为实际应用中根据成像质量要求选择参考界限提供了理论依据。",
                "source_handles": [
                  "P0002"
                ]
              }
            ],
            "evidence_and_conditions": [
              {
                "source_handle": "P0002",
                "finding": "在两种不同的焦点位置定义（r0=Ftan(α) 和 r0=Fα）下，带宽界限均表现出随 FOV 增加而减小并最终饱和的趋势。",
                "conditions": "适用于具有有限横向尺寸的平面金属透镜，聚焦于平面焦平面。"
              }
            ],
            "transition": "确立了色散工程带来的带宽物理界限后，必须指出即使色散被完美校正，单层超构透镜仍面临另一重独立的硬限制——几何像差。"
          },
          {
            "unit_id": "U4",
            "theme": "单界面几何像差的独立硬限制",
            "substantive_point": "结合 P0001 视角，指出单界面结构无法校正高阶几何像差，构成 FOV 的另一重硬性限制，独立于色散工程的带宽限制之外。",
            "development": "引入 P0001 的批判性分析，指出单层超构透镜仅有一个界面进行相位调制，无法像多片式复合物镜那样通过空间分离校正彗差、像散和场曲。特别是在高 NA 条件下，这些几何像差在大视场下会迅速破坏衍射极限成像，将有效视场限制在极小范围内。",
            "paragraph_briefs": [
              {
                "point": "单界面几何像差的物理起源",
                "development": "基于 P0001 的几何光学解释，说明法向入射与斜入射所需理想相位分布的差异在小孔径和小角度展开后对应于彗差、场曲和像散。单层结构缺乏空间自由度来补偿这些像差。",
                "source_handles": [
                  "P0001"
                ]
              },
              {
                "point": "高 NA 下的视场硬性截断",
                "development": "引用 P0001 的具体数据，指出对于 NA=0.5 的高数值孔径超构透镜，在可见光范围内，若要求路径延迟误差不超过一个波长（保持低像差），其有效视场被限制在小于 5 µm 的范围内。这构成了 FOV 的另一重独立于色散限制的硬边界。",
                "source_handles": [
                  "P0001"
                ]
              }
            ],
            "evidence_and_conditions": [
              {
                "source_handle": "P0001",
                "finding": "对于 NA=0.5 的单层超构透镜，在可见光范围内路径延迟误差不超过一个波长的低像差视场非常小（小于 5 µm）。",
                "conditions": "研究对象为单层平面超构透镜，排除多元件复合系统。"
              }
            ],
            "transition": "本章通过量化分析确立了可见光消色差超构透镜在带宽和视场上的双重物理天花板。下一章将深入微观层面，探讨为了实现这种色散补偿，具体的纳米结构设计是如何引入效率损耗的。"
          }
        ]
      }
    }
  ],
  "unit_id_remap": {}
}

